const b = ($input.first().json.body) || $input.first().json || {};
const event = (b.event || '').toString();
const d = b.data || {};
const cust = d.customer || {};
const meta = d.metadata || {};
const email = (cust.email || meta.email || '').toString().trim().toLowerCase();
const first = (cust.first_name || meta.first_name || '').toString().trim();
const last = (cust.last_name || meta.last_name || '').toString().trim();
const phone = (cust.phone || meta.phone || '').toString().trim();
const plan = (meta.plan || (d.plan && d.plan.name) || '').toString().trim();
const amount = Number(d.amount || 0) / 100;
const reference = (d.reference || '').toString();
return [{ json: { event, email, first_name: first, last_name: last, phone, plan, amount, reference, go_live_date: new Date().toISOString().slice(0,10) } }];
